#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/text/localizable/localizable_property.hpp"
#include "gui_forms/control/shared_capabilities/shared_capabilities.hpp"
#include "gui_forms/commands/color_command/color_command.hpp"
#include "gui_forms/types.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// RibbonColorPicker's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/ribbon_color_picker.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The colour command whose value the picker shows and commits, or null; without one the picker keeps its own value.
template <typename Declaring>
struct RibbonColorPickerCommandCapability {
    PropertyCell<std::shared_ptr<ColorCommand>, RibbonColorPickerCommandCapability<Declaring>> command{};

    static void assign(RibbonColorPickerCommandCapability& capability, std::shared_ptr<ColorCommand> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.command), incoming);
        if (!capability.command.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.command));
    }
};

// The colour shown, or none for Automatic: the command's, or the picker's own. A write goes to the command's set_value when there is one.
template <typename Declaring>
struct RibbonColorPickerValueCapability {
    PropertyView<std::optional<Color>, RibbonColorPickerValueCapability<Declaring>> value;

    static void assign(RibbonColorPickerValueCapability& capability, std::optional<Color> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.value), std::move(incoming));
    }

    static std::optional<Color> read(const RibbonColorPickerValueCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::optional<Color> current = control.read_view(capability.value);
        return current;
    }
};

// The face's icon, over the colour bar.
template <typename Declaring>
struct RibbonColorPickerImageCapability {
    PropertyCell<ImageId, RibbonColorPickerImageCapability<Declaring>> image{};

    static void assign(RibbonColorPickerImageCapability& capability, ImageId incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.image), incoming);
        if (!capability.image.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.image));
    }
};

// Every RibbonColorPicker capability, in the order the declaring class takes them.
template <typename Declaring>
struct RibbonColorPickerCapabilities : public RibbonColorPickerCommandCapability<Declaring>,
                                       public RibbonColorPickerValueCapability<Declaring>,
                                       public RibbonColorPickerImageCapability<Declaring>,
                                       public TextCapability<Declaring> {
    RibbonColorPickerCapabilities() : TextCapability<Declaring>(std::string{"Colour"}) {}
};

} // namespace gui_forms
